<?php $isApproval=$page==='approvals';$firstCount=count(array_filter($all,fn($b)=>$isApproval?$b['status']==='Pendente':($b['date']>=date('Y-m-d')&&in_array($b['status'],['Pendente','Confirmado'],true))));$secondCount=$isApproval?count($all):count($all)-$firstCount; ?>
<div class="<?= $isApproval?'approval-list':'reservation-list' ?>"><div class="segmented-tabs"><a class="<?= in_array($tab,['pending','upcoming'],true)?'selected':'' ?>" href="<?= e(url($page)) ?>"><?= $isApproval?'Pendentes':'Próximas' ?> (<?= $firstCount ?>)</a><a class="<?= in_array($tab,['all','past'],true)?'selected':'' ?>" href="<?= e(url($page,['tab'=>$isApproval?'all':'past'])) ?>"><?= $isApproval?'Todas':'Passadas' ?> (<?= $secondCount ?>)</a></div>
<?php foreach($rows as $b): ?><article class="card booking-card"><div class="date-tile"><strong><?= date('d',strtotime($b['date'])) ?></strong><small><?= month_short($b['date']) ?></small></div><div class="grow"><div class="row-title"><h3><a href="<?= e(url('rooms',['action'=>'show','id'=>$b['room_id']])) ?>"><?= e($b['room_name']) ?></a></h3><?= badge($b['status']) ?></div><p><?= e($b['purpose']) ?></p><div class="booking-meta"><?php if($isApproval): ?><span><?= icon('users') ?><?= e($b['teacher']) ?></span><?php endif; ?><span><?= icon('clock') ?><?= e(substr($b['start_time'],0,5).' – '.substr($b['end_time'],0,5)) ?></span><span><?= icon('calendar-days') ?>Solicitado em <?= e(date_br($b['created_at'])) ?></span></div><?php if($b['notes']): ?><p class="booking-notes"><?= e($b['notes']) ?></p><?php endif; ?></div>
<?php if($isApproval&&$b['status']==='Pendente'&&$b['date']>=date('Y-m-d')): ?><div class="actions approval-actions"><?php foreach(['approve'=>['check','Aprovar'],'reject'=>['x','Recusar']] as $act=>[$i,$label]): ?><form method="post" action="<?= e(url('approvals',['action'=>$act,'id'=>$b['id']])) ?>" <?= $act==='reject'?'data-confirm="Recusar esta solicitação de reserva?"':'' ?>><?= csrf_field() ?><button class="button button-small <?= $act==='reject'?'button-outline':'' ?>"><?= icon($i) ?><?= $label ?></button></form><?php endforeach; ?></div><?php elseif(!$isApproval&&$tab!=='past'): ?><form method="post" action="<?= e(url('reservations',['action'=>'cancel','id'=>$b['id']])) ?>" data-confirm="Cancelar esta reserva? O horário será liberado para outros professores."><?= csrf_field() ?><button class="icon-button" aria-label="Cancelar reserva de <?= e($b['room_name']) ?>" title="Cancelar reserva"><?= icon('trash-2') ?></button></form><?php endif; ?></article><?php endforeach;if(!$rows){empty_state($isApproval?'Nenhuma solicitação nesta lista':'Nenhuma reserva nesta lista',$isApproval?'As novas solicitações aparecerão aqui.':'Explore as salas e encontre o ambiente ideal para sua aula.');} ?></div>
